import React from "react";
import React, {
  ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import { useSSR } from "./use-ssr";

const ELEMENT_NODE = 1;
const TEXT_NODE = 3;

type ComponentOrElement<T> =
  | Element
  | Text
  | React.Component
  | React.RefObject<T>
  | null
  | undefined;

/**
 * A safe, typed alternative to findDOMNode.
 * Works with:
 * 1. DOM Elements (returns them directly)
 * 2. Ref Objects (returns .current)
 * 3. Null/Undefined (returns null)
 * NOT SUPPORTED: Passing a Class Component instance directly (legacy behavior).
 * You must use a Ref for Components.
 */
export default function findDOMNode<T = Element | Text>(
  componentOrElement: ComponentOrElement<T>,
): T | null {
  if (componentOrElement === null) {
    return null;
  }

  if (componentOrElement && "nodeType" in componentOrElement) {
    const node = componentOrElement as Node;
    if (node.nodeType === ELEMENT_NODE || node.nodeType === TEXT_NODE) {
      return node as unknown as T;
    }
  }

  if (
    componentOrElement &&
    "current" in componentOrElement &&
    componentOrElement.current !== null
  ) {
    return (componentOrElement as React.RefObject<T>).current;
  }

  if (process.env.NODE_ENV !== "production") {
    console.warn(
      "[findDOMNode] You passed a Component instance or an unknown object. " +
        "This utility cannot strictly find DOM nodes from Component instances (like the deprecated react-dom version could). " +
        "Please pass a Ref (ref.current) or a direct DOM element.",
    );
  }

  return null;
}

export type HTMLElRef = React.MutableRefObject<HTMLElement>;
export type CustomEvent = {
  event?: React.SyntheticEvent<any, Event>;
  portal: HTMLElRef;
  targetEl: HTMLElRef;
} & React.SyntheticEvent<any, Event>;

export type CustomEventHandler = (customEvent: CustomEvent) => void;
export type CustomEventHandlers = {
  [K in keyof React.DOMAttributes<K>]?: CustomEventHandler;
};

export type EventListenerMap = {
  [K in keyof React.DOMAttributes<K>]: keyof GlobalEventHandlersEventMap;
};

export type EventListenersRef = React.MutableRefObject<{
  [K in keyof React.DOMAttributes<K>]?: (
    event: React.SyntheticEvent<any, Event>,
  ) => void;
}>;

export type UsePortalOptions = {
  /**
   * Close the portal when clicking outside the portal content.
   * @default true
   */
  closeOnOutsideClick?: boolean;
  /**
   * Close the portal when the Escape key is pressed.
   * @default true
   */
  closeOnEsc?: boolean;
  /**
   * The DOM element to attach the portal to.
   * @default document.body
   */
  bindTo?: HTMLElement;
  /**
   * Initial open state.
   * @default false
   */
  isOpen?: boolean;
  /** Callback fired when the portal opens. */
  onOpen?: CustomEventHandler;
  /** Callback fired when the portal closes. */
  onClose?: CustomEventHandler;
  /** Callback fired when the portal content is clicked. */
  onPortalClick?: CustomEventHandler;
  /** Set to true if managing open state entirely outside this hook.
   * @default false
   */
  programmaticallyOpen?: boolean;
} & CustomEventHandlers;

export type UsePortalObjectReturn = {};
export type UsePortalArrayReturn = [];

export const errorMessage1 =
  "You must either add a `ref` to the element you are interacting with or pass an `event` to openPortal(e) or togglePortal(e) when the `programmaticallyOpen` option is not set to `true`.";

/**
 * Custom hook to manage the creation and state of DOM Portals.
 * Handles mounting, unmounting, outside clicks, and "Escape" key closure.
 * @category dom
 * @param {UsePortalOptions} [options={}] - Configuration options for the portal.
 * @returns {UsePortalObjectReturn & UsePortalArrayReturn} A hybrid object/array containing the Portal component, open/close functions, and refs.
 * @see [Documentation](https://sse-hooks.vercel.app/docs/hooks/use-portal)
 * @public
 */
export function usePortal({
  closeOnOutsideClick = true,
  closeOnEsc = true,
  bindTo,
  isOpen: defaultIsOpen = false,
  onOpen,
  onClose,
  onPortalClick,
  programmaticallyOpen = false,
  ...eventHandlers
}: UsePortalOptions = {}) {
  const { isServer, isBrowser } = useSSR();
  const [isOpen, makeOpen] = useState(defaultIsOpen);
  const open = useRef(isOpen);

  const setOpen = useCallback((v: boolean) => {
    open.current = v;
    makeOpen(v);
  }, []);

  // @ts-expect-error
  const targetEl = useRef() as HTMLElRef;
  const portal = useRef(
    isBrowser ? document.createElement("div") : null,
  ) as HTMLElRef;

  useEffect(() => {
    if (isBrowser && !portal.current) {
      portal.current = document.createElement("div");
    }
  }, [isBrowser, portal]);

  const elToMountTo = useMemo(() => {
    if (isServer) return;
    return (bindTo && findDOMNode(bindTo)) || document.body;
  }, [isServer, bindTo]);

  const createCustomEvent = (e: any) => {
    if (!e) return { portal, targetEl, event: e };
    const event = e || {};
    if (event.persist) event.persist();
    event.portal = portal;
    event.targetEl = targetEl;
    event.event = e;
    const { currentTarget } = e;
    if (!targetEl.current && currentTarget && currentTarget !== document) {
      targetEl.current = event.currentTarget;
    }
    return event;
  };

  // this should handle all eventHandlers like onClick, onMouseOver, etc. passed into the config
  const customEventHandlers: CustomEventHandlers = Object.entries(
    eventHandlers,
  ).reduce<any>((acc, [handlerName, eventHandler]) => {
    acc[handlerName] = (event?: React.SyntheticEvent<any, Event>) => {
      if (isServer) return;
      eventHandler(createCustomEvent(event));
    };
    return acc;
  }, {});

  const openPortal = useCallback(
    (e: any) => {
      if (isServer) return;
      const customEvent = createCustomEvent(e);
      // for some reason, when we don't have the event argument, there
      // is a weird race condition. Would like to see if we can remove
      // setTimeout, but for now this works
      if (targetEl.current == null && !programmaticallyOpen) {
        setTimeout(() => setOpen(true), 0);
        throw Error(errorMessage1);
      }
      if (onOpen) onOpen(customEvent);
      setOpen(true);
    },
    [isServer, portal, setOpen, targetEl, onOpen],
  );

  const closePortal = useCallback(
    (e: any) => {
      if (isServer) return;
      const customEvent = createCustomEvent(e);
      if (onClose && open.current) onClose(customEvent);
      if (open.current) setOpen(false);
    },
    [isServer, onClose, setOpen],
  );

  const togglePortal = useCallback(
    (e: React.SyntheticEvent<any, Event>): void =>
      open.current ? closePortal(e) : openPortal(e),
    [closePortal, openPortal],
  );

  const handleKeydown = useCallback(
    (e: KeyboardEvent): void =>
      e.key === "Escape" && closeOnEsc ? closePortal(e) : undefined,
    [closeOnEsc, closePortal],
  );

  const handleOutsideMouseClick = useCallback(
    (e: MouseEvent): void => {
      const containsTarget = (target: HTMLElRef) =>
        target.current.contains(e.target as HTMLElement);
      // There might not be a targetEl if the portal was opened programmatically.
      if (
        containsTarget(portal) ||
        (e as any).button !== 0 ||
        !open.current ||
        (targetEl.current && containsTarget(targetEl))
      )
        return;

      if (closeOnOutsideClick) closePortal(e);
    },
    [isServer, closePortal, closeOnOutsideClick, portal],
  );

  const handleMouseDown = useCallback(
    (e: MouseEvent): void => {
      if (isServer || !(portal.current instanceof HTMLElement)) return;
      const customEvent = createCustomEvent(e);
      if (
        portal.current.contains(customEvent.target as HTMLElement) &&
        onPortalClick
      )
        onPortalClick(customEvent);
      handleOutsideMouseClick(e);
    },
    [handleOutsideMouseClick],
  );

  const eventListeners = useRef({}) as EventListenersRef;

  useEffect(() => {
    if (isServer) return;
    if (
      !(elToMountTo instanceof HTMLElement) ||
      !(portal.current instanceof HTMLElement)
    )
      return;

    // TODO: eventually will need to figure out a better solution for this.
    // Surely we can find a way to map onScroll/onWheel -> scroll/wheel better,
    // but for all other event handlers. For now this works.
    const eventHandlerMap: EventListenerMap = {
      onScroll: "scroll",
      onWheel: "wheel",
    };
    const node = portal.current;
    elToMountTo.appendChild(portal.current);
    // handles all special case handlers. Currently only onScroll and onWheel
    Object.entries(eventHandlerMap).forEach(
      ([handlerName /* onScroll */, eventListenerName /* scroll */]) => {
        if (!eventHandlers[handlerName as keyof EventListenerMap]) return;
        eventListeners.current[handlerName as keyof EventListenerMap] = (
          e: any,
        ) =>
          (eventHandlers[handlerName as keyof EventListenerMap] as any)(
            createCustomEvent(e),
          );
        document.addEventListener(
          eventListenerName as keyof GlobalEventHandlersEventMap,
          eventListeners.current[handlerName as keyof EventListenerMap] as any,
        );
      },
    );
    document.addEventListener("keydown", handleKeydown);
    document.addEventListener("mousedown", handleMouseDown as any);

    return () => {
      // handles all special case handlers. Currently only onScroll and onWheel
      Object.entries(eventHandlerMap).forEach(
        ([handlerName, eventListenerName]) => {
          if (!eventHandlers[handlerName as keyof EventListenerMap]) return;
          document.removeEventListener(
            eventListenerName as keyof GlobalEventHandlersEventMap,
            eventListeners.current[
              handlerName as keyof EventListenerMap
            ] as any,
          );
          delete eventListeners.current[handlerName as keyof EventListenerMap];
        },
      );
      document.removeEventListener("keydown", handleKeydown);
      document.removeEventListener("mousedown", handleMouseDown as any);
      elToMountTo.removeChild(node);
    };
  }, [isServer, handleOutsideMouseClick, handleKeydown, elToMountTo, portal]);

  const Portal = useCallback(
    ({ children }: { children: ReactNode }) => {
      if (portal.current != null) return createPortal(children, portal.current);
      return null;
    },
    [portal],
  );

  return Object.assign(
    [
      openPortal,
      closePortal,
      open.current,
      Portal,
      togglePortal,
      targetEl,
      portal,
    ],
    {
      isOpen: open.current,
      openPortal,
      ref: targetEl,
      closePortal,
      togglePortal,
      Portal,
      portalRef: portal,
      ...customEventHandlers,
      bind: {
        // used if you want to spread all html attributes onto the target element
        ref: targetEl,
        ...customEventHandlers,
      },
    },
  );
}

